def _processMessage(self, msg):
    """
    process the msg, and put the result in the output buffer
    msg (str): raw message (including header)
    """
    res = None
    wspaces = msg.count(' ')
    qmarks = msg.count('?')
    tokens = msg.split()
    if ((wspaces > 1) and (qmarks > 0)) or (wspaces > 2) or (qmarks > 1):
        res = "ERROR: Cannot parse this command\n"
    elif qmarks:
        if tokens[0] == "*IDN?":
            res = IDN + '\n'
        elif tokens[0] == "PWR?":
            pin = int(tokens[1])
            if (pin < 0) or (pin > 7):
                res = "ERROR: Out of range pin number\n"
            else:
                ans = (self._i2crcv >> pin) & MASK
                res = str(ans) + '\n'
        else:
            res = "ERROR: Cannot parse this command\n"
    elif wspaces:
        pin = int(tokens[1])
        val = int(tokens[2])
        if tokens[0] == "PWR":
            if (pin < 0) or (pin > 7):
                res = "ERROR: Out of range pin number\n"
            else:
                self._i2crcv = (self._i2crcv & ~(1 << pin)) | ((val << pin) & (1 << pin))
                res = '\n'
        # TODO: add support for WMEM and RMEM
        else:
            res = "ERROR: Cannot parse this command\n"
    else:
        res = "ERROR: Cannot parse this command\n"

    # add the response end
    if res is not None:
        self._output_buf += res
